SELECT f.FCLT_BUILDING_KEY,f.FLOOR,f.ASSIGNABLE_AREA,f.NON_ASSIGNABLE_AREA,(f.ASSIGNABLE_AREA / (f.ASSIGNABLE_AREA + f.NON_ASSIGNABLE_AREA)) * 100 AS PERCENT_ASSIGNABLE_AREA
FROM fclt_floor AS f
WHERE (f.ASSIGNABLE_AREA + f.NON_ASSIGNABLE_AREA) IS NOT NULLAND (f.ASSIGNABLE_AREA + f.NON_ASSIGNABLE_AREA) > 0;

SELECT HR_ORG_UNIT_TITLE,COUNT(*) AS num_employees,SUM(CASE WHEN HAS_ADDL_APPOINTMENT = 'Y' THEN 1 ELSE 0 END) AS num_with_addl_appointment,SUM(CASE WHEN HAS_DUAL_APPOINTMENT = 'Y' THEN 1 ELSE 0 END) AS num_with_dual_appointment
FROM drupal_employee_directory
GROUP BY HR_ORG_UNIT_TITLE;

SELECT DEPARTMENT, COURSE_LEVEL, COUNT(*) AS number_of_programs
FROM student_degree_program
GROUP BY DEPARTMENT, COURSE_LEVEL WITH ROLLUP;

SELECT DEPARTMENT_NAME,COUNT(CASE WHEN IS_OFFERED_FALL_TERM = 'Y' THEN SUBJECT_ID END) AS FALL_TERM_COUNT,COUNT(CASE WHEN IS_OFFERED_SPRING_TERM = 'Y' THEN SUBJECT_ID END) AS SPRING_TERM_COUNT,COUNT(CASE WHEN IS_OFFERED_IAP = 'Y' THEN SUBJECT_ID END) AS IAP_COUNT
FROM cis_course_catalog
GROUP BY DEPARTMENT_NAME;

SELECT SUBJECT_CODE, SUBJECT_TITLE, DEPARTMENT_NAME, MEETS_WITH_SUBJECTS, TOTAL_UNITS
FROM course_catalog_subject_offered
WHERE ACADEMIC_YEAR = '2024' AND MEETS_WITH_SUBJECTS IS NOT NULL AND MEETS_WITH_SUBJECTS <> '';

SELECT sos.SUBJECT_ID,sos.SUBJECT_TITLE,sos.OFFER_DEPT_NAME,sos.TOTAL_UNITS,sos.NUM_ENROLLED_STUDENTS,sos.NUM_ENROLLED_STUDENTS - dept_avg.avg_enrollment AS enrollment_difference_from_dept_avg
FROM subject_offered_summary AS sos
JOIN (SELECT   OFFER_DEPT_NAME,  AVG(NUM_ENROLLED_STUDENTS) AS avg_enrollmentFROM   subject_offered_summaryWHERE   TERM_CODE = '2022FA'GROUP BY   OFFER_DEPT_NAME
) AS dept_avg ON sos.OFFER_DEPT_NAME = dept_avg.OFFER_DEPT_NAME
WHERE sos.TERM_CODE = '2022FA';

SELECT SUBJECT_ID, SUBJECT_TITLE, DEPARTMENT_NAME, SUBJECT_ENROLLMENT_FIRST_WEEK, SUBJECT_ENROLLMENT_FIFTH_WEEK, (SUBJECT_ENROLLMENT_FIFTH_WEEK - SUBJECT_ENROLLMENT_FIRST_WEEK) AS ENROLLMENT_CHANGE
FROM subject_summary
WHERE TERM_CODE = '2022FA';

SELECT BUILDING_NUMBER, BUILDING_NAME, BLDG_GROSS_SQUARE_FOOTAGE, BLDG_ASSIGNABLE_SQUARE_FOOTAGE, (BLDG_ASSIGNABLE_SQUARE_FOOTAGE / BLDG_GROSS_SQUARE_FOOTAGE) * 100 AS ASSIGNABLE_PERCENTAGE
FROM buildings
WHERE BLDG_GROSS_SQUARE_FOOTAGE IS NOT NULL AND BLDG_GROSS_SQUARE_FOOTAGE <> 0;
